package co.edu.icesi.pdg.mte.governance;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import java.math.BigDecimal;
import java.util.*;
import static co.edu.icesi.pdg.mte.governance.GovernanceV2Service.error;
@Service @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
public class ConsistencyV2Service {
    private final JdbcTemplate jdbc;private final TrackingV2Service tracking;private final PoliciesV2Service policies;
    public ConsistencyV2Service(JdbcTemplate jdbc,TrackingV2Service tracking,PoliciesV2Service policies){this.jdbc=jdbc;this.tracking=tracking;this.policies=policies;}
    public List<Map<String,Object>> departments(){var actor=tracking.actor();return tracking.jsonRows("SELECT id,name FROM department"+(actor.admin()?"":" WHERE id="+actor.departmentId())+" ORDER BY name,id");}
    public Map<String,Object> check(Long cycle,Long department){
        var actor=tracking.actor();if(cycle==null || cycle<=0)throw error(HttpStatus.UNPROCESSABLE_ENTITY,"INVALID_CYCLE");
        if(jdbc.queryForObject("SELECT COUNT(*) FROM strategic_cycle WHERE id=?",Long.class,cycle)!=1)throw error(HttpStatus.NOT_FOUND,"OUT_OF_SCOPE");
        if(department!=null && (!actor.admin() && department!=actor.departmentId() || jdbc.queryForObject("SELECT COUNT(*) FROM department WHERE id=?",Long.class,department)!=1))throw error(HttpStatus.NOT_FOUND,"OUT_OF_SCOPE");
        String dept="COALESCE(o.department_id,(SELECT p.department_id FROM kr_assignment a JOIN professor p ON p.id=a.professor_id WHERE a.key_result_id=k.id AND a.ended_at IS NULL ORDER BY a.id DESC LIMIT 1))";
        String filter=department==null?"":" AND "+dept+"="+department;
        var krs=tracking.jsonRows("SELECT k.id,k.name,k.base_value AS base,k.target_value AS target,k.unit_of_measure_id AS \"krUnit\",m.unit_of_measure_id AS \"metricUnit\",m.active AS \"metricActive\",u.active AS \"unitActive\",u.type,u.decimal_precision AS precision,d.active AS \"departmentActive\",(SELECT COUNT(*) FROM kr_assignment a JOIN professor p ON p.id=a.professor_id JOIN department pd ON pd.id=p.department_id WHERE a.key_result_id=k.id AND a.ended_at IS NULL AND p.active=TRUE AND pd.active=TRUE) AS owners,(SELECT COUNT(*) FROM kr_goal_link l JOIN goal g ON g.id=l.goal_id WHERE l.key_result_id=k.id AND l.ended_at IS NULL AND g.active=TRUE) AS goals,(SELECT COUNT(*) FROM kr_bet_link l JOIN strategic_bet b ON b.id=l.strategic_bet_id WHERE l.key_result_id=k.id AND l.ended_at IS NULL AND b.active=TRUE) AS bets FROM key_result k LEFT JOIN objective o ON o.id=k.objective_id LEFT JOIN department d ON d.id="+dept+" LEFT JOIN metric_definition m ON m.id=k.metric_definition_id LEFT JOIN unit_of_measure u ON u.id=m.unit_of_measure_id WHERE "+tracking.scope(actor)+" AND k.strategic_cycle_id=? AND k.active=TRUE AND k.status NOT IN ('CLOSED','CERRADO')"+filter+" ORDER BY k.id LIMIT 1001",cycle);
        String initiativeScope=actor.admin()?"1=1":"i.department_id="+actor.departmentId();
        String initiativeFilter=department==null?"":" AND i.department_id="+department;
        var initiatives=tracking.jsonRows("SELECT i.id,i.title,i.department_id AS \"departmentId\",d.active AS \"departmentActive\",(SELECT COUNT(*) FROM initiative_assignment a JOIN professor p ON p.id=a.professor_id WHERE a.initiative_id=i.id AND a.ended_at IS NULL AND p.active=TRUE AND p.department_id=i.department_id) AS owners FROM initiative i JOIN key_result k ON k.id=i.key_result_id JOIN department d ON d.id=i.department_id WHERE "+initiativeScope+" AND k.strategic_cycle_id=? AND i.active=TRUE AND i.status<>'CLOSED'"+initiativeFilter+" ORDER BY i.id LIMIT 1001",cycle);
        var tasks=tracking.jsonRows("SELECT t.id,t.title_snapshot AS title,t.initiative_id AS \"initiativeId\",c.consent_status AS consent,c.revoked_at AS revoked FROM planner_task_ref t JOIN planner_connection c ON c.id=t.connection_id JOIN initiative i ON i.id=t.initiative_id JOIN key_result k ON k.id=i.key_result_id WHERE "+initiativeScope+" AND k.strategic_cycle_id=? AND i.active=TRUE"+initiativeFilter+" ORDER BY t.id LIMIT 2001",cycle);
        if(krs.size()>1000 || initiatives.size()>1000 || tasks.size()>2000)throw error(HttpStatus.CONFLICT,"CONSISTENCY_TOO_LARGE");
        PoliciesV2Service.Policy policy=null;String policyState="READY";
        try{policy=policies.current(false);if(policy==null)policyState="POLICY_UNSET";}catch(co.edu.icesi.pdg.mte.common.BusinessException e){if(!"INVALID_POLICY".equals(e.getMessage()))throw e;policyState="INVALID_POLICY";}
        var findings=new ArrayList<Map<String,Object>>();
        for(var kr:krs){long id=((Number)kr.get("id")).longValue();String name=kr.get("name").toString();
            if(!Boolean.TRUE.equals(kr.get("metricActive")) || !Boolean.TRUE.equals(kr.get("unitActive")))add(findings,"KR_METRIC","KR",id,"HIGH",name,"La ficha métrica o su unidad falta o está inactiva.","Revisar ficha y unidad del KR.",null);
            if(kr.get("metricUnit")!=null && !Objects.equals(kr.get("krUnit"),kr.get("metricUnit")))add(findings,"KR_UNIT_MISMATCH","KR",id,"HIGH",name,"La unidad guardada del KR difiere de la ficha métrica.","Conciliar la definición del KR conservando mediciones anteriores.",null);
            if(!validValues(kr))add(findings,"KR_VALUES","KR",id,"HIGH",name,"Base o valor esperado incompletos o incompatibles con la unidad.","Revisar base, valor esperado y precisión del KR.",null);
            if(((Number)kr.get("owners")).longValue()!=1)add(findings,"KR_OWNER","KR",id,"HIGH",name,"El KR no tiene exactamente un responsable vigente activo.","Revisar la asignación e historial del responsable.",null);
            if(!Boolean.TRUE.equals(kr.get("departmentActive")))add(findings,"KR_DEPARTMENT","KR",id,"HIGH",name,"La unidad departamental falta o está inactiva.","Revisar el departamento y la asignación del KR.",null);
            if(policy!=null){if(((Number)kr.get("goals")).longValue()<policy.minGoals())add(findings,"KR_GOAL_MINIMUM","KR",id,"HIGH",name,"Metas vigentes: "+kr.get("goals")+"; mínimo registrado: "+policy.minGoals()+".","Revisar los vínculos a Metas.",PoliciesV2Service.KEY);if(((Number)kr.get("bets")).longValue()<policy.minBets())add(findings,"KR_BET_MINIMUM","KR",id,"HIGH",name,"Apuestas vigentes: "+kr.get("bets")+"; mínimo registrado: "+policy.minBets()+".","Revisar los vínculos a Apuestas.",PoliciesV2Service.KEY);}
        }
        for(var initiative:initiatives){long id=((Number)initiative.get("id")).longValue();if(((Number)initiative.get("owners")).longValue()!=1)add(findings,"INITIATIVE_OWNER","INITIATIVE",id,"HIGH",initiative.get("title").toString(),"La iniciativa no tiene exactamente un responsable activo de su departamento.","Revisar el responsable de la iniciativa.",null);if(!Boolean.TRUE.equals(initiative.get("departmentActive")))add(findings,"INITIATIVE_DEPARTMENT","INITIATIVE",id,"HIGH",initiative.get("title").toString(),"El departamento de la iniciativa está inactivo.","Revisar la unidad organizacional.",null);}
        for(var task:tasks)if(task.get("revoked")!=null || !"ACTIVE".equals(task.get("consent"))){add(findings,"PLANNER_CONNECTION","PLANNER_TASK",((Number)task.get("id")).longValue(),"MEDIUM",Objects.toString(task.get("title"),"Tarea sin título"),"La conexión de esta referencia está revocada o sin consentimiento activo.","Consultar las tareas y el estado de conexión de la iniciativa "+task.get("initiativeId")+".",null);findings.get(findings.size()-1).put("initiativeId",task.get("initiativeId"));}
        var blocked=new ArrayList<String>(List.of("CHECKIN_CADENCE","PLANNER_FRESHNESS"));if(policy==null)blocked.addAll(List.of("KR_GOAL_MINIMUM","KR_BET_MINIMUM"));
        var result=new LinkedHashMap<String,Object>();result.put("cycleId",cycle);result.put("departmentId",department);result.put("auditStatus",policyState);result.put("policyVersion",policy==null?null:policy.version());result.put("evaluationStatus","PARTIAL");result.put("blockedRules",blocked);result.put("findings",findings);result.put("totalFindings",findings.size());result.put("checked",Map.of("keyResults",krs.size(),"initiatives",initiatives.size(),"taskReferences",tasks.size()));result.put("asOf",jdbc.queryForObject("SELECT CURRENT_TIMESTAMP",java.sql.Timestamp.class).toInstant().toString());return result;
    }
    private boolean validValues(Map<String,Object> kr){if(kr.get("base")==null || kr.get("target")==null || kr.get("precision")==null)return false;for(String field:List.of("base","target")){BigDecimal value=new BigDecimal(kr.get(field).toString());if(value.stripTrailingZeros().scale()>Math.min(2,((Number)kr.get("precision")).intValue()))return false;if("PORCENTAJE".equals(kr.get("type"))&&(value.signum()<0||value.compareTo(BigDecimal.valueOf(100))>0))return false;if("BOOLEANA".equals(kr.get("type"))&&value.compareTo(BigDecimal.ZERO)!=0&&value.compareTo(BigDecimal.ONE)!=0)return false;}return true;}
    private void add(List<Map<String,Object>> findings,String rule,String type,long id,String severity,String title,String description,String action,String policy){var finding=new LinkedHashMap<String,Object>();finding.put("findingId",type+":"+id+":"+rule);finding.put("ruleCode",rule);finding.put("entityType",type);finding.put("entityId",id);finding.put("severity",severity);finding.put("title",title);finding.put("description",description);finding.put("recommendedAction",action);finding.put("policyCode",policy);findings.add(finding);}
}
